import * as core from '@actions/core';
const query = /* GraphQL */ `
  query listSteps(
    $checkSuiteId: ID!,
    $checkRunConclusions: [CheckConclusionState!],
  ) {
    node(id: $checkSuiteId) {
      __typename
      ... on CheckSuite {
        checkRuns(first: 100, filterBy: { checkType: LATEST, status: COMPLETED, conclusions: $checkRunConclusions }) {
          nodes {
            databaseId
            steps(first: 100) {
              nodes {
                name
                status
                conclusion
                startedAt
                completedAt
              }
            }
          }
        }
      }
    }
  }
`;
export const getListStepsQuery = async (octokit, v) => core.group(`ListStepsQuery(${JSON.stringify(v)})`, async () => await octokit.graphql(query, v));
